"""Exact discriminant of the lattice generated by vectors with a given integral Gram matrix (15/10/2026).

lattice_disc(G): G = n x n symmetric integer PSD Gram matrix (Python ints), rank r.  Returns (r, disc) where disc is the
determinant of the Gram matrix of a Z-basis of the lattice generated by the n vectors.  Method: r independent indices I
(pivots mod a large prime), D = det G_II (Bareiss), N = adj-solution so that the other vectors are N_j / D in the
I-basis, index [Lambda : Lambda_I] = D^r / [Z^r : D Z^r + sum Z N_j] (Hermite reduction modulo D), disc = D / index^2.
"""
import math

PR = (1 << 61) - 1


def pivots_mod_p(G, p=PR):
    n = len(G)
    A = [[x % p for x in row] for row in G]
    piv, r = [], 0
    rows = list(range(n))
    for c in range(n):
        q = next((i for i in range(r, n) if A[i][c] != 0), None)
        if q is None:
            continue
        A[r], A[q] = A[q], A[r]
        inv = pow(A[r][c], p - 2, p)
        A[r] = [(x * inv) % p for x in A[r]]
        for i in range(n):
            if i != r and A[i][c]:
                f = A[i][c]
                A[i] = [(x - f * y) % p for x, y in zip(A[i], A[r])]
        piv.append(c)
        r += 1
    return piv


def det_bareiss(H):
    r = len(H)
    M = [list(row) for row in H]
    prev, sign = 1, 1
    for k in range(r - 1):
        q = next((i for i in range(k, r) if M[i][k] != 0), None)
        if q is None:
            return 0
        if q != k:
            M[k], M[q] = M[q], M[k]
            sign = -sign
        for i in range(k + 1, r):
            M[i] = [(M[k][k] * M[i][j] - M[i][k] * M[k][j]) // prev if j > k else 0 for j in range(r)]
        prev = M[k][k]
    return sign * M[r - 1][r - 1]


def solve_fraction_free(H, B):
    """Return (D, N) with H N = D B, D = det H, N integer (via exact rational elimination on the big-integer level)."""
    from fractions import Fraction as Fr
    r = len(H)
    m = len(B[0])
    A = [[Fr(H[i][j]) for j in range(r)] + [Fr(B[i][j]) for j in range(m)] for i in range(r)]
    for c in range(r):
        q = next(i for i in range(c, r) if A[i][c] != 0)
        A[c], A[q] = A[q], A[c]
        pv = A[c][c]
        A[c] = [x / pv for x in A[c]]
        for i in range(r):
            if i != c and A[i][c] != 0:
                f = A[i][c]
                A[i] = [x - f * y for x, y in zip(A[i], A[c])]
    X = [row[r:] for row in A]
    D = det_bareiss(H)
    N = [[x * D for x in row] for row in X]
    assert all(x.denominator == 1 for row in N for x in row)
    return D, [[int(x) for x in row] for row in N]


def index_mod(rows, r, D):
    """[Z^r : D Z^r + sum Z rows] by Hermite reduction modulo D (D > 0)."""
    rows = [[x % D for x in row] for row in rows]
    rows = [row for row in rows if any(row)]
    det = 1
    for c in range(r):
        # combine the entries of column c of all rows and of D e_c into one pivot g = gcd(...)
        g = D
        piv = [0] * r
        piv[c] = D
        extra = []
        for row in rows:
            a = row[c]
            if a == 0:
                continue
            # extended gcd of (piv[c], a)
            x0, y0, gg = egcd(piv[c], a)
            # new pivot = x0 * piv + y0 * row ; residual = (a/gg) * piv - (piv[c]/gg) * row (has 0 in column c)
            newp = [(x0 * p_ + y0 * q_) % D if j != c else gg for j, (p_, q_) in enumerate(zip(piv, row))]
            res = [((a // gg) * p_ - (piv[c] // gg) * q_) % D for p_, q_ in zip(piv, row)]
            res[c] = 0
            piv = newp
            if any(res):
                extra.append(res)
        rest = [row for row in rows if row[c] == 0] + extra
        g = piv[c]
        # the D e_c generator: D e_c = (D/g) * piv - (D/g) * (piv - g e_c) ; residual (D/g) * (piv with column c removed)
        resD = [((D // g) * x) % D for x in piv]
        resD[c] = 0
        if any(resD):
            rest.append(resD)
        det *= g
        rows = [row for row in rest if any(row)]
    return det


def egcd(a, b):
    if b == 0:
        return (1, 0, a) if a >= 0 else (-1, 0, -a)
    x0, y0, x1, y1 = 1, 0, 0, 1
    while b:
        q = a // b
        a, b = b, a - q * b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    if a < 0:
        a, x0, y0 = -a, -x0, -y0
    return x0, y0, a


def lattice_disc(G):
    n = len(G)
    I = pivots_mod_p(G)
    r = len(I)
    H = [[G[a][b] for b in I] for a in I]
    rest = [j for j in range(n) if j not in I]
    if not rest:
        return r, det_bareiss(H)
    B = [[G[a][j] for j in rest] for a in I]
    D, N = solve_fraction_free(H, B)
    if D < 0:
        D, N = -D, [[-x for x in row] for row in N]
    cols = [[N[i][k] for i in range(r)] for k in range(len(rest))]
    sub = index_mod(cols, r, D)  # [Z^r : D Z^r + sum Z N_j]
    assert (D ** r) % sub == 0
    idx = D ** r // sub          # [Lambda : Lambda_I] (coordinates: Lambda_I = Z^r, Lambda = Z^r + sum Z N_j / D)
    assert (D % (idx * idx)) == 0, "disc not integral: D=%d idx=%d" % (D, idx)
    return r, D // (idx * idx)


def factor_small(N, bound=200000):
    N = abs(N)
    f = {}
    for p in [2, 3]:
        while N % p == 0:
            f[p] = f.get(p, 0) + 1
            N //= p
    p = 5
    while p <= bound and p * p <= N:
        for q in (p, p + 2):
            while N % q == 0:
                f[q] = f.get(q, 0) + 1
                N //= q
        p += 6
    if 1 < N <= bound * bound:
        f[N] = f.get(N, 0) + 1
        N = 1
    return f, N
